+// The audit trail: one entry per request that may change data.
+
+/** Appends an audit entry (time `at`, key name, method, path, status) to the store. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit.push({ at, key, method, path, status });
+}
+
+/** The audit entries, newest first. */
+export function listAudit(store) {
+  return store.data.audit.map((e, i) => [e, i]).sort((a, b) => (a[0].at < b[0].at ? 1 : a[0].at > b[0].at ? -1 : b[1] - a[1])).map(([e]) => e);
+}
