+// API keys and roles. Checks only who may call what; no business rules.
+import { AppError } from "../errors.js";
+
+const RANK = { viewer: 0, cook: 1, manager: 2 };
+
+// Routes below manager level: [method, path pattern, lowest role].
+const RULES = [
+  ["GET", /^\/audit$/, "manager"],
+  ["POST", /^\/recipes\/[^/]+\/cook$/, "cook"],
+  ["POST", /^\/batches\/[^/]+\/waste$/, "cook"],
+  ["POST", /^\/temperatures$/, "cook"],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/, "cook"],
+];
+
+/** The API key record for the request's bearer token; throws unauthorized if none. */
+export function authenticate(store, headers) {
+  const raw = Object.entries(headers).find(([k]) => k.toLowerCase() === "authorization")?.[1];
+  const m = typeof raw === "string" ? /^Bearer (.+)$/.exec(raw.trim()) : null;
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found || !(found.role in RANK)) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws forbidden unless `role` may call `method` on `path`. */
+export function authorize(role, method, path) {
+  const rule = RULES.find(([m, re]) => m === method && re.test(path));
+  const needed = rule ? rule[2] : method === "GET" ? "viewer" : "manager";
+  if (RANK[role] < RANK[needed]) throw new AppError("forbidden", { role });
+}
